// Define all K-9 services to monitor
const services = [
  { name: 'k9-llm-router', url: 'http://localhost:8765/health', port: 8765, tier: 'critical' },
  { name: 'k9-orchestrator', url: 'http://localhost:8744/health', port: 8744, tier: 'critical' },
  { name: 'k9-paymaster', url: 'http://localhost:9002/health', port: 9002, tier: 'critical' },
  { name: 'k9-mcp-manager', url: 'http://localhost:3030/health', port: 3030, tier: 'critical' },
  { name: 'k9-quant-engine', url: 'http://localhost:9001/health', port: 9001, tier: 'important' },
  { name: 'aeg-token-model', url: 'http://localhost:9003/health', port: 9003, tier: 'important' },
  { name: 'aeg-signal-router', url: 'http://localhost:9004/health', port: 9004, tier: 'important' },
  { name: 'k9-sentiment-engine', url: 'http://localhost:9006/health', port: 9006, tier: 'monitor' },
  { name: 'k9-polymarket-adapter', url: 'http://localhost:9007/gex/health', port: 9007, tier: 'monitor' },
  { name: 'k9-gex-engine', url: 'http://localhost:9008/gex/health', port: 9008, tier: 'monitor' },
  { name: 'n8n', url: 'http://localhost:5678/healthz', port: 5678, tier: 'infra' },
  { name: 'ollama', url: 'http://localhost:11434/api/tags', port: 11434, tier: 'infra' }
];

return services.map(s => ({ json: s }));

// Aggregate health results
const items = [];
const allItems = $('Health Check').all();
const services = $('Service List').all();

let healthy = 0, unhealthy = 0, critical_down = 0;
const downServices = [];

for (let i = 0; i < services.length; i++) {
  const svc = services[i].json;
  const resp = allItems[i];
  const isHealthy = resp && resp.json && !resp.error;

  if (isHealthy) {
    healthy++;
  } else {
    unhealthy++;
    if (svc.tier === 'critical') critical_down++;
    downServices.push(svc.name);
  }
}

const total = services.length;
const healthPercent = Math.round((healthy / total) * 100);

// Build summary
let summary = `K-9 Health: ${healthPercent}% (${healthy}/${total} up)`;
if (critical_down > 0) {
  summary = `🔴 CRITICAL: ${critical_down} critical services down! ${downServices.join(', ')}`;
} else if (unhealthy > 0) {
  summary = `🟡 ${unhealthy} services down: ${downServices.join(', ')}`;
} else {
  summary = `🟢 All ${total} K-9 services healthy`;
}

// Determine if alert needed
const isAlert = critical_down > 0 || unhealthy >= 3;

items.push({
  json: {
    timestamp: new Date().toISOString(),
    health_percent: healthPercent,
    healthy_count: healthy,
    unhealthy_count: unhealthy,
    critical_down: critical_down,
    down_services: downServices,
    summary,
    is_alert: isAlert,
    type: 'ecosystem_health'
  }
});

return items;
